class GroupGate:
    def __init__(self, n): self.n, self.done, self.leak, self.scored = n, 0, False, 0; self.ev = asyncio.Event()
    async def settle(self, session_id, out, leak=False, masked=None):
        self.done += 1; self.leak |= bool(leak); self.scored += int(out is not None and masked is None)
        if self.done >= self.n: self.ev.set()
        await asyncio.wait_for(self.ev.wait(), timeout=GATE_TIMEOUT_SEC)   # every session must reach settle() via try/finally
        if masked is not None or self.leak or self.scored < 2:
            return []                                                      # not stored -> no gradient, not in the group mean
        return out

